"""Migrated Meridian CRM 4.2 order_fulfilment workflow."""

from decimal import Decimal
from typing import Any, Callable


def _legacy_numeric(value: Any) -> Decimal:
    """Coerce a legacy value for numeric comparison."""
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Decimal(0)
    return Decimal(str(value))


def _first_live_account(record: dict, tables: dict) -> dict | None:
    """Return the first live ACCT_MASTER row matching the record's ACCT_ID."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row
    return None


def _approve_guard(record: dict, tables: dict) -> bool:
    del tables
    return _legacy_numeric(record.get("TOT_AMT", "")) > 0


def _account_cancel_guard(record: dict, tables: dict) -> bool:
    account = _first_live_account(record, tables)
    credit_hold = "" if account is None else account.get("CRED_HOLD", "")
    if credit_hold is None:
        credit_hold = ""
    return credit_hold != "Y"


Transition = tuple[
    str,
    str,
    str,
    Callable[[dict, dict], bool] | None,
    tuple[tuple[str, str], ...],
]


# Document order is significant: the first matching transition fires.
_TRANSITIONS: tuple[Transition, ...] = (
    ("E", "A", "approve", _approve_guard, (("audit", "ORD_APPR"),)),
    (
        "A",
        "S",
        "ship",
        None,
        (("audit", "ORD_SHIP"), ("notify", "shipped")),
    ),
    ("S", "I", "invoice", None, (("audit", "ORD_INV"),)),
    ("E", "X", "cancel", None, (("audit", "ORD_CANC"),)),
    (
        "A",
        "X",
        "cancel",
        _account_cancel_guard,
        (("audit", "ORD_CANC"),),
    ),
    (
        "I",
        "X",
        "cancel",
        None,
        (("audit", "ORD_CANC_INV"), ("notify", "credit_note")),
    ),
)


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first eligible order_fulfilment transition."""
    record_copy = dict(record)

    for from_state, to_state, transition_event, guard, actions in _TRANSITIONS:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record, tables):
            continue

        audits: list[str] = []
        notifies: list[str] = []
        for action_type, value in actions:
            if action_type == "audit":
                audits.append(value)
            else:
                notifies.append(value)

        return {
            "state": to_state,
            "record": record_copy,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
